package com.citacloud.springboot.contacloud.app.views;

import com.citacloud.springboot.contacloud.app.dto.*;
import com.citacloud.springboot.contacloud.app.models.EstadoAgenteImpresion;
import com.citacloud.springboot.contacloud.app.security.TenantContext;
import com.citacloud.springboot.contacloud.app.services.*;
import com.citacloud.springboot.contacloud.app.views.components.*;
import com.vaadin.flow.component.*;
import com.vaadin.flow.component.combobox.ComboBox;
import com.vaadin.flow.component.confirmdialog.ConfirmDialog;
import com.vaadin.flow.component.dialog.Dialog;
import com.vaadin.flow.component.html.*;
import com.vaadin.flow.component.notification.Notification;
import com.vaadin.flow.component.orderedlayout.*;
import com.vaadin.flow.component.textfield.TextField;
import com.vaadin.flow.data.value.ValueChangeMode;
import com.vaadin.flow.router.*;
import jakarta.annotation.security.PermitAll;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.*;

@Route(value="configuracion/impresion-pos/agentes",layout=MainLayout.class)
@PageTitle("Agentes de impresión | ContaCloud") @PermitAll
public class AgentesImpresionView extends VerticalLayout implements BeforeEnterObserver {
    private static final DateTimeFormatter DATE=DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm");
    private final PrintAgentAdminService service;private final EmpresaModuloService modules;
    private final TextField search=new TextField("Buscar");private final ComboBox<EstadoAgenteImpresion> status=new ComboBox<>("Estado");
    private final AppGrid<AgenteImpresionDto> grid=new AppGrid<>(AgenteImpresionDto.class);private final AppPagination pagination;
    public AgentesImpresionView(PrintAgentAdminService service,EmpresaModuloService modules){this.service=service;this.modules=modules;addClassName("cc-page");setPadding(false);setSpacing(false);setWidthFull();Component create=can("agentes_impresion.crear")?new AppActionButton(ActionType.NEW,ButtonSize.MAIN,"Nuevo agente de impresión",e->form()):null;add(create==null?new AppPageHeader("AGENTES DE IMPRESIÓN","Administra los dispositivos autorizados para contaCloudPrint."):new AppPageHeader("AGENTES DE IMPRESIÓN","Administra los dispositivos autorizados para contaCloudPrint.",create));search.setPlaceholder("Nombre o identificador...");search.setClearButtonVisible(true);search.setValueChangeMode(ValueChangeMode.LAZY);search.setValueChangeTimeout(400);status.setItems(EstadoAgenteImpresion.values());status.setItemLabelGenerator(AgentesImpresionView::estado);status.setClearButtonVisible(true);search.addValueChangeListener(e->{if(e.isFromClient())reset();});status.addValueChangeListener(e->{if(e.isFromClient())reset();});HorizontalLayout filters=new HorizontalLayout(search,status);filters.addClassName("cc-filter-bar");filters.setAlignItems(Alignment.END);filters.setWidthFull();configureGrid();pagination=new AppPagination(r->load());add(filters,grid,pagination);}
    @Override public void beforeEnter(BeforeEnterEvent event){if(!modules.habilitado("CONFIGURACION")||!can("agentes_impresion.ver")){Notification.show("No tienes permiso para acceder a esta opción.");event.rerouteTo(DashboardView.class);return;}load();}
    private void configureGrid(){grid.addColumn(AgenteImpresionDto::nombre).setHeader("Nombre").setFlexGrow(1);grid.addColumn(AgenteImpresionDto::sucursal).setHeader("Sucursal").setFlexGrow(1);grid.addColumn(AgenteImpresionDto::codigo).setHeader("Identificador").setAutoWidth(true);grid.addComponentColumn(this::badge).setHeader("Estado").setAutoWidth(true);grid.addColumn(a->a.ultimaConexion()==null?"—":DATE.format(a.ultimaConexion().atZoneSameInstant(ZoneId.systemDefault()))).setHeader("Última conexión").setAutoWidth(true);grid.addComponentColumn(this::actions).setHeader("Acc.").setAutoWidth(true).setFlexGrow(0);grid.setEmptyStateText("No hay agentes de impresión registrados.");}
    private Component actions(AgenteImpresionDto agent){HorizontalLayout row=new HorizontalLayout();row.addClassName("cc-grid-actions");row.setPadding(false);row.setSpacing(false);row.add(new AppActionButton(ActionType.VIEW,ButtonSize.GRID_ACTION,"Ver agente de impresión",e->detail(agent.id())));return row;}
    private void load(){if(pagination==null)return;try{var req=pagination.currentRequest();var page=service.buscar(search.getValue(),status.getValue(),req.page(),req.size());grid.setItems(page.getContent());pagination.setTotal(page.getTotalElements());}catch(RuntimeException ex){error(ex,"No fue posible cargar los agentes de impresión.");}}
    private void reset(){pagination.reset();load();}
    private void form(){try{List<PrintAgentAdminService.OpcionSucursal> options=service.sucursales();Dialog d=dialog("NUEVO AGENTE DE IMPRESIÓN","720px");TextField name=new TextField("Nombre del agente");name.setMaxLength(150);name.setRequiredIndicatorVisible(true);ComboBox<PrintAgentAdminService.OpcionSucursal> branch=new ComboBox<>("Sucursal");branch.setItems(options);branch.setItemLabelGenerator(PrintAgentAdminService.OpcionSucursal::nombre);branch.setRequiredIndicatorVisible(true);Div fields=new Div(name,branch);fields.addClassName("cc-dialog-form");d.add(fields);AppActionButton save=new AppActionButton(ActionType.SAVE,ButtonSize.MAIN,"Guardar",null);save.addClickListener(e->{save.setEnabled(false);try{AgenteImpresionDto created=service.crear(new CrearAgenteImpresionInput(name.getValue(),branch.getValue()==null?null:branch.getValue().id()));d.close();load();Notification.show("Agente creado correctamente.");detail(created.id());}catch(RuntimeException ex){save.setEnabled(true);error(ex,"No fue posible crear el agente de impresión.");}});d.getFooter().add(save,new AppActionButton(ActionType.CANCEL,ButtonSize.MAIN,"Cancelar",e->d.close()));d.open();}catch(RuntimeException ex){error(ex,"No fue posible abrir el formulario.");}}
    private void detail(UUID id){try{AgenteImpresionDto a=service.obtener(id);Dialog d=dialog("AGENTE DE IMPRESIÓN","820px");Div heading=new Div(new H2(a.nombre()),badge(a));heading.addClassName("cc-detail-heading");d.add(heading,new AppDetailSection("INFORMACIÓN GENERAL").field("Identificador",a.codigo()).field("Sucursal",a.sucursal()).field("Estado",estadoVisual(a)).field("Última conexión",a.ultimaConexion()==null?"—":DATE.format(a.ultimaConexion().atZoneSameInstant(ZoneId.systemDefault()))).field("Equipo",display(a.nombreMaquina())).field("Versión de contaCloudPrint",display(a.versionAplicacion())).field("Sistema operativo",display(a.sistemaOperativo())));if(a.estado()==EstadoAgenteImpresion.PENDING&&can("agentes_impresion.codigo"))d.getFooter().add(new AppActionButton(ActionType.LINK,ButtonSize.MAIN,"Generar código de vinculación",e->{try{CodigoVinculacionDto code=service.generarCodigo(a.id());showCode(code);d.close();}catch(RuntimeException ex){error(ex,"No fue posible generar el código de vinculación.");}}));if(a.estado()!=EstadoAgenteImpresion.REVOKED&&can("agentes_impresion.revocar"))d.getFooter().add(new AppActionButton(ActionType.VOID,ButtonSize.MAIN,"Revocar agente",e->confirmRevoke(a,d)));d.getFooter().add(new AppActionButton(ActionType.CLOSE,ButtonSize.MAIN,"Cerrar",e->d.close()));d.open();}catch(RuntimeException ex){error(ex,"No fue posible consultar el agente de impresión.");}}
    private void showCode(CodigoVinculacionDto code){Dialog d=dialog("CÓDIGO DE VINCULACIÓN","560px");Paragraph intro=new Paragraph("Ingresa este código en contaCloudPrint. Es temporal, de un solo uso y el código anterior quedó invalidado.");H1 value=new H1(code.codigo());value.getStyle().set("letter-spacing","0.25em").set("text-align","center");Paragraph expires=new Paragraph("Expira: "+DATE.format(code.expiraEn().atZoneSameInstant(ZoneId.systemDefault())));d.add(intro,value,expires);d.getFooter().add(new AppActionButton(ActionType.CLOSE,ButtonSize.MAIN,"Cerrar",e->d.close()));d.open();}
    private void confirmRevoke(AgenteImpresionDto a,Dialog parent){ConfirmDialog c=new ConfirmDialog();c.setHeader("Revocar agente");c.setText("El dispositivo perderá acceso inmediatamente y sus credenciales no podrán reutilizarse. ¿Deseas continuar?");c.setCancelable(true);c.setCancelText("Cancelar");c.setConfirmText("Revocar");c.setConfirmButtonTheme("error primary");c.addConfirmListener(e->{try{service.revocar(a.id());parent.close();load();Notification.show("Agente revocado correctamente.");}catch(RuntimeException ex){error(ex,"No fue posible revocar el agente.");}});c.open();}
    private Span badge(AgenteImpresionDto a){String text=estadoVisual(a);Span badge=new Span(text);String theme=a.estado()==EstadoAgenteImpresion.REVOKED?"error":a.estado()==EstadoAgenteImpresion.PENDING?"contrast":a.conectado()?"success":"contrast";badge.getElement().getThemeList().add("badge "+theme);return badge;}
    private static String estadoVisual(AgenteImpresionDto a){if(a.estado()==EstadoAgenteImpresion.REVOKED)return "Revocado";if(a.estado()==EstadoAgenteImpresion.PENDING)return "Pendiente";return a.conectado()?"Conectado":"Desconectado";}
    private static String estado(EstadoAgenteImpresion e){return switch(e){case PENDING->"Pendiente";case ACTIVE->"Activo";case REVOKED->"Revocado";};}
    private static Dialog dialog(String title,String width){Dialog d=new Dialog();d.setHeaderTitle(title);d.setWidth(width);return d;}private static boolean can(String p){return TenantContext.principalActual().permisos().contains(p);}private static String display(String v){return v==null||v.isBlank()?"—":v;}private static void error(RuntimeException ex,String fallback){String message=ex instanceof ReglaNegocioException||ex instanceof RecursoNoEncontradoException?ex.getMessage():fallback;Notification.show(message==null||message.isBlank()?fallback:message);}
}
